#include <bits/stdc++.h>

using namespace std;

int main() {
    int t;
    cin >> t;
    while (t--) {
        int n;
        cin >> n;

        int m = 3 * n;
        vector < long long > s(m + 1, 0);
        for (int i = 1; i <= m; i++) {
            cin >> s[i];
        }

        sort(s.begin() + 1, s.end(), greater < long long > ());

        vector < long long > p(m + 1, 0);
        for (int i = 1; i <= m; i++) {
            p[i] = p[i - 1] + s[i];
        }

        long long best = 0;
        for (int a = 0; a <= n; a++) {
            int low = 0, high = n - a;

            while (low < high) {
                int mid = (low + high) / 2;

                long long d = s[a + 2 * mid + 1] + s[a + 2 * mid + 2] - 3 * s[3 * n - 2 * a - mid];
                if (d > 0) low = mid + 1;
                else high = mid;
            }
            int b = low;
            int j = a + 2 * b;
            int k = 3 * n - 2 * a - b;
            long long asdf = 2 * p[a] + p[j] + 3 * p[k];
            best = max(best, asdf);

        }
        cout << best << endl;

    }
}
